function generateBreadcrumbs(){let e=document.getElementById("breadcrumbs");if(!e)return;e.innerHTML="";let t=window.location.pathname.split("/").filter(e=>e.length>0),n="",r=document.querySelector("h1"),a=r?r.textContent:document.title;t=t.filter(e=>"index.php"!==e);let l=window.location.search?window.location.search.substring(1):null;t.forEach((r,i)=>{n+="/"+r;let o=i===t.length-1,c=capitalizeFirstLetterOfEachWord(r.replace(/-/g," ")),p=document.createElement("li");if(o)p.textContent=c,"mmenu"===r?p.textContent=`Home > ${a}`:r.endsWith(".php")&&(p.textContent=a);else{let h=document.createElement("a");h.href=n,0===i&&(h.href="/mmenu.php"),l&&"inactivity"!==l&&(h.href+=`?${l}`),h.textContent="mmenu"===r?"Home":c,p.appendChild(h);let d=document.createElement("span");d.setAttribute("aria-hidden","true"),d.setAttribute("data-symbol",">"),d.textContent=" > ",p.appendChild(d)}e.appendChild(p)})}function capitalizeFirstLetterOfEachWord(e){return e.replace(/\b\w/g,e=>e.toUpperCase())}window.onload=generateBreadcrumbs;